// Some portions generated by Claude
import { repositoryScope } from "./repository-identity.ts";

/**
 * Every write the Workbench makes to a repository (Add RDF, Remove, Clear, SPARQL Update, configuration, creating or
 * deleting it) puts a new value under this key (scripts/ts/graphAdditions.ts, dataChanged). The Graph page keys its
 * cached Filters values by that value, so a write in this tab or another one makes it load them again.
 */
const DATA_REVISION_PREFIX = "rdf4j-workbench-data-revision:";

export function dataRevisionKey(basePath: string, repositoryId: string, serverIdentity: string) {
  return DATA_REVISION_PREFIX + repositoryScope(basePath, repositoryId, serverIdentity);
}

type ReadableStorage = { getItem(key: string): string | null };

/** The repository's current data revision: "0" until the Workbench first writes to it. */
export function readDataRevision(key: string, storage?: ReadableStorage | null) {
  try {
    const target = storage ?? (typeof localStorage === "undefined" ? null : localStorage);
    return target?.getItem(key) || "0";
  } catch {
    return "0";
  }
}

type EventTarget = {
  addEventListener(type: "storage", listener: (event: { key: string | null; newValue: string | null }) => void): void;
  removeEventListener(type: "storage", listener: (event: { key: string | null; newValue: string | null }) => void): void;
};

/** Calls `onChange` with the new revision whenever another tab writes to this repository; returns the unsubscriber. */
export function watchDataRevision(key: string, onChange: (revision: string) => void, target?: EventTarget | null) {
  const source = target ?? (typeof window === "undefined" ? null : (window as unknown as EventTarget));
  if (!source) return () => {};
  const listener = (event: { key: string | null; newValue: string | null }) => {
    if (event.key === key) onChange(event.newValue || "0");
  };
  source.addEventListener("storage", listener);
  return () => source.removeEventListener("storage", listener);
}
